package main

import (
	"context"
	"fmt"
	"os"
	"strings"

	"google.golang.org/protobuf/types/known/structpb"

	commonv1 "github.com/mellifera/mellifera/proto/mellifera/common/v1"
	metadatav1 "github.com/mellifera/mellifera/proto/mellifera/metadata/v1"
)

// Document/query keys this plugin dispatches on. The dispatch keys are the
// serial module's document-shape vocabulary (serial-parser stamps season/
// episode; the film path stamps title with neither) plus the parsed year the
// movie search disambiguates on; the emitted keys are the query keys
// BuildRequest consumes (1.3).
const (
	idKey      = "tmdb_id"
	titleKey   = "title"
	seasonKey  = "season"
	episodeKey = "episode"
	yearKey    = "year"

	// The serial module's serial-record document vocabulary (the scanner's
	// stamp: serial_record/dir_name_raw/series_relative_path). Read here as a
	// plain fact — the plugin never imports core or the scanner. A
	// serial-record parsed carries NO display title (the chain feeds every
	// source a base built from parsed alone and never writes a derived title
	// back), so a bare serial record skips here; a marker document that DOES
	// carry a title is a series, never a movie — the marker routes it to the
	// tv search even when no season key rides along. The SAME season fact
	// rides an anchored query when the document carries one — BuildRequest's
	// anchored plan takes the tv-detail + season-extra path only when the
	// query carries the season — while an anchored movie document stays
	// season-free.
	serialRecordKey = "serial_record"
)

// sourceImpl is the server-side MetadataSource capability for tmdb. It is
// STATELESS between RPCs (arch §0.2): every output is a pure function of the
// request, so a crash loses no in-flight work. Match dispatches on the
// document shape alone (the core carries no media-kind knowledge);
// BuildRequest shapes the core-executed fetch (mode A) with the api key
// resolved core-side; Convert normalizes the raw payload into the RU-first
// namespace; Merge writes ONLY document.sources["tmdb"] (arch §3.3) — the
// core stamps _provenance/_view authoritatively (INV-namespace-write).
type sourceImpl struct{}

// Match decides whether this item carries a document tmdb can enrich and,
// when it does, builds the query the rest of the chain consumes. Dispatch is
// DOCUMENT-SHAPE only: an ID anchor (identifiers.tmdb_id, surfaced by the
// core as existing_ids) wins over any shape with confidence 1.0 and a reason
// recording the anchor — the document's season fact rides the anchored query
// when it carries one (the anchored series plan's season fetch derives its n
// from it), an anchored movie document staying season-free; an episode
// document (season + episode keys) never
// applies — episode files get no tmdb namespace (their titles arrive through
// the anchored series run's season contributions instead); a series document
// (a title with a season, or a serial-record marker document carrying a
// title) applies via the tv search, the season carried in the query for
// disambiguation (defaulting to 1 for a marker document without one, the
// serial-parser adapter precedent — a record names a series); a film-parsed
// document (a title with no season/episode keys and no marker) applies via
// the movie search carrying the title and the parsed year. A non-applying
// document is a skipped stage, not an error.
func (*sourceImpl) Match(_ context.Context, req *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	if id, ok := intField(req.GetExistingIds(), idKey); ok && id > 0 {
		q := map[string]any{idKey: id}
		if season, hasSeason := seasonField(req.GetItem().GetParsed().GetFields()); hasSeason && season > 0 {
			// The season rides the anchored query (BuildRequest's anchored
			// plan keys the tv-detail + season-extra path on it); an anchored
			// movie document stays season-free.
			q[seasonKey] = season
		}
		return &metadatav1.MatchResult{
			Applies:     true,
			Query:       toStruct(q),
			Confidence:  1.0,
			Reason:      fmt.Sprintf("matched by tmdb_id %d", id),
			ResolvedIds: toStruct(map[string]any{idKey: id}),
		}, nil
	}
	f := req.GetItem().GetParsed().GetFields()
	if _, hasEpisode := f[episodeKey]; hasEpisode {
		return &metadatav1.MatchResult{Applies: false, Reason: "episode document: episode files carry no tmdb namespace"}, nil
	}
	title := f[titleKey].GetStringValue()
	if title == "" {
		return &metadatav1.MatchResult{Applies: false, Reason: "no display title in document"}, nil
	}
	season, hasSeason := seasonField(f)
	if hasSeason || f[serialRecordKey].GetBoolValue() {
		if !hasSeason {
			// The always-season rule mirrors serial-parser's adapter default:
			// a record names a series even when no marker or stamped key
			// carries a season — it is season 1.
			season = 1
		}
		return &metadatav1.MatchResult{
			Applies:    true,
			Query:      toStruct(map[string]any{titleKey: title, seasonKey: season}),
			Confidence: 0.6,
			Reason:     "series document tv search",
		}, nil
	}
	q := map[string]any{titleKey: title}
	if year, hasYear := yearField(f); hasYear && year > 0 {
		q[yearKey] = year
	}
	return &metadatav1.MatchResult{
		Applies:    true,
		Query:      toStruct(q),
		Confidence: 0.6,
		Reason:     "film document movie search",
	}, nil
}

// seasonField reads the season key's numeric value from a parsed field map
// (presence-keyed; ok=false when the key is absent).
func seasonField(f map[string]*structpb.Value) (int64, bool) {
	v, ok := f[seasonKey]
	if !ok {
		return 0, false
	}
	return int64(v.GetNumberValue()), true
}

// yearField reads the year key's numeric value from a parsed field map
// (presence-keyed; ok=false when the key is absent).
func yearField(f map[string]*structpb.Value) (int64, bool) {
	v, ok := f[yearKey]
	if !ok {
		return 0, false
	}
	return int64(v.GetNumberValue()), true
}

// intField reads a numeric field from a Struct (presence-keyed; 0 for null).
func intField(s *structpb.Struct, key string) (int64, bool) {
	v, ok := s.GetFields()[key]
	if !ok {
		return 0, false
	}
	return int64(v.GetNumberValue()), true
}

// toStruct wraps a JSON-safe map; the maps here are all plugin-controlled
// literals, so the (unreachable) error is ignored — mirrors tv-parser.
func toStruct(m map[string]any) *structpb.Struct {
	st, _ := structpb.NewStruct(m)
	return st
}

// --- BuildRequest: the SERVER request contract (the core executes the
// fetch, mode A) ---

// Request-contract constants. minIntervalMS=250 is TMDB's light pacing (the
// upstream allows ~50 rps; the core's FetchGate enforces the interval
// server-side); languageRU pins RU-first so Convert's namespace is
// russian-first. The api key NEVER rides a literal: it is declared
// required_secrets ["api_key"] (pluginsvc.go) and referenced in every
// template through the redacted_ref variable scoped "server:api_key" — the
// core resolves it from the store-backed binding config at execution time
// and the secret value never enters this process.
const (
	minIntervalMS = 250
	languageRU    = "ru-RU"

	// languageVar/apiKeyVar are the {placeholder} names every template
	// carries; apiKeyRef is the scope:name redacted_ref the executor
	// resolves server-side (request_spec.proto §6.2).
	languageVar = "language"
	apiKeyVar   = "api_key"
	apiKeyRef   = "server:" + apiKeyVar

	// upstreamEnvVar is the hermetic-test seam (the shikimori
	// MELLIFERA_SHIKIMORI_UPSTREAM precedent): when set in this plugin
	// process's environment (the joint-test server passes it through —
	// plugin children inherit the server env), it replaces the API base in
	// EVERY template, so a test fetch never leaves the machine. Production
	// never sets it; the default is the real upstream.
	upstreamEnvVar = "MELLIFERA_TMDB_UPSTREAM"

	// defaultAPIBase is the production upstream INCLUDING the /3 version
	// prefix — the compile-time value the seam falls back to (the unit
	// tests pin the templates' literal shapes against it).
	defaultAPIBase = "https://api.themoviedb.org/3"

	// sharedParams is the query suffix every template carries: the RU-first
	// language and the server-scoped secret reference. The api_key
	// placeholder substitutes from the redacted_ref variable — the key's
	// literal value appears in no template, ever.
	sharedParams = "&language={language}&api_key={api_key}"
)

// anchoredQuery is sharedParams as a COMPLETE query string — the leading
// "&" becomes the leading "?". The search bases already carry "?query=" and
// join sharedParams directly; the four anchored paths carry no query of
// their own, so they must join anchoredQuery. Composing the "&"-led suffix
// onto a bare path built the unparseable "/movie/{tmdb_id}&language=…"
// hybrid the joint wire caught (the QA stub saw GET
// /3/movie/700101&language=… with an empty RawQuery).
var anchoredQuery = "?" + strings.TrimPrefix(sharedParams, "&")

// apiBase is resolved ONCE at process start (package-var initialization, so
// before Serve accepts its first RPC): the env override when present (trailing
// slashes trimmed; an empty or slash-only value falls back), else
// defaultAPIBase. The templates below reference it, so Go initializes them
// after it — they always carry the resolved base.
var apiBase = upstreamBase()

// upstreamBase reads the seam. Pure over the environment so the unit tests
// can pin the override and fallback branches; the one real read happens once,
// in apiBase's initializer.
func upstreamBase() string {
	if v := strings.TrimRight(os.Getenv(upstreamEnvVar), "/"); v != "" {
		return v
	}
	return defaultAPIBase
}

// Endpoint templates. Every URL composes apiBase so the seam swaps them all;
// substitution is {placeholder}-only — the core percent-encodes the
// substituted values (request_spec.proto). Every template's path joins its
// params with an explicit query separator: the search bases carry
// "?query=" and take the "&"-led sharedParams suffix directly; the anchored
// paths are bare and take the "?"-led anchoredQuery — so every composed URL
// is a parseable path?query string. The year filter joins only when the
// query carries a parsed year (the variable MUST exist whenever the
// template references it).
var (
	movieSearchBase     = apiBase + "/search/movie?query={title}"
	tvSearchBase        = apiBase + "/search/tv?query={title}"
	movieSearchTemplate = movieSearchBase + sharedParams
	tvSearchTemplate    = tvSearchBase + sharedParams
	movieDetailTemplate = apiBase + "/movie/{tmdb_id}" + anchoredQuery
	creditsTemplate     = apiBase + "/movie/{tmdb_id}/credits" + anchoredQuery
	tvDetailTemplate    = apiBase + "/tv/{tmdb_id}" + anchoredQuery
	seasonTemplate      = apiBase + "/tv/{tmdb_id}/season/{season}" + anchoredQuery
)

// BuildRequest shapes the fetch the core executes server-side (mode A). The
// api key rides ONLY as the redacted_ref variable scoped server:api_key —
// the core resolves it from the binding's store-backed config before
// execution, so the secret value never enters this process; every spec
// carries language=ru-RU and the light 250 ms pacing. An anchored query
// (tmdb_id, the Match anchor) resolves to the detail plan: the tv-detail
// primary plus the season fetch as an extra when the query carries a season
// (the season fetch's n IS the query's own season fact), the movie-detail
// primary plus the credits fetch as an extra otherwise. An unanchored query
// takes the search endpoint its shape names: the movie search carrying the
// parsed year when one rides the query, the tv search otherwise (the season
// rides the query for disambiguation, never into the URL). Substitution is
// {placeholder}-only; the core percent-encodes the values.
func (*sourceImpl) BuildRequest(_ context.Context, req *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	f := req.GetQuery().GetFields()
	res := &metadatav1.BuildRequestResponse{}
	if id, ok := intField(req.GetQuery(), idKey); ok && id > 0 {
		vars := tmdbVars(map[string]*metadatav1.VariableValue{idKey: intVar(id)})
		if _, isSeries := f[seasonKey]; isSeries {
			season, has := seasonField(f)
			if !has || season <= 0 {
				// The always-season rule mirrors Match's marker default:
				// a series plan names a season even when the query's key
				// carries nothing usable — it is season 1.
				season = 1
			}
			vars[seasonKey] = intVar(season)
			res.Spec = tmdbSpec(tvDetailTemplate, vars)
			res.ExtraSpecs = []*metadatav1.RequestSpec{seasonSpec(id, season)}
			return res, nil
		}
		res.Spec = tmdbSpec(movieDetailTemplate, vars)
		res.ExtraSpecs = []*metadatav1.RequestSpec{creditsSpec(id)}
		return res, nil
	}
	vars := tmdbVars(map[string]*metadatav1.VariableValue{titleKey: stringVar(f[titleKey].GetStringValue())})
	template := movieSearchTemplate
	if _, isSeries := f[seasonKey]; isSeries {
		// A series query takes the tv search; the season it carries
		// disambiguates upstream-side and never enters the URL.
		template = tvSearchTemplate
	} else if year, hasYear := yearField(f); hasYear && year > 0 {
		template = movieSearchBase + "&year={year}" + sharedParams
		vars[yearKey] = intVar(year)
	}
	res.Spec = tmdbSpec(template, vars)
	return res, nil
}

// creditsSpec shapes the companion credits fetch (the convention cast
// source): the movie's credits under the SAME request contract as the
// primary — the ru-RU language and the server-scoped secret reference, the
// 250 ms pacing. It rides the anchored film plan as extras[0].
func creditsSpec(id int64) *metadatav1.RequestSpec {
	return tmdbSpec(creditsTemplate, tmdbVars(map[string]*metadatav1.VariableValue{idKey: intVar(id)}))
}

// seasonSpec shapes the companion season fetch (episode-titles source): the
// series' season n under the SAME request contract as the primary. It rides
// the anchored series plan as extras[0] — after the primary, the ordered
// extras position the core executes second.
func seasonSpec(id, season int64) *metadatav1.RequestSpec {
	return tmdbSpec(seasonTemplate, tmdbVars(map[string]*metadatav1.VariableValue{
		idKey:     intVar(id),
		seasonKey: intVar(season),
	}))
}

// tmdbSpec shapes a GET under the shared request contract: the light pacing,
// the language + secret-reference placeholders already baked into the
// template, and the per-endpoint substitution variables.
func tmdbSpec(template string, vars map[string]*metadatav1.VariableValue) *metadatav1.RequestSpec {
	return &metadatav1.RequestSpec{
		Method:        "GET",
		UrlTemplate:   template,
		Variables:     vars,
		MinIntervalMs: minIntervalMS,
	}
}

// tmdbVars seeds a spec's variable map with the contract pair every tmdb
// spec carries — the RU-first language and the server-scoped secret
// reference — then layers the caller's per-endpoint variables on top.
func tmdbVars(extra map[string]*metadatav1.VariableValue) map[string]*metadatav1.VariableValue {
	vars := map[string]*metadatav1.VariableValue{
		languageVar: stringVar(languageRU),
		apiKeyVar:   redactedVar(apiKeyRef),
	}
	for k, v := range extra {
		vars[k] = v
	}
	return vars
}

// intVar wraps an integer substitution value.
func intVar(v int64) *metadatav1.VariableValue {
	return &metadatav1.VariableValue{Kind: &metadatav1.VariableValue_IntValue{IntValue: v}}
}

// stringVar wraps a string substitution value.
func stringVar(v string) *metadatav1.VariableValue {
	return &metadatav1.VariableValue{Kind: &metadatav1.VariableValue_StringValue{StringValue: v}}
}

// redactedVar wraps a scope:name secret reference — the executor resolves it
// server-side; the secret value never crosses into this process.
func redactedVar(ref string) *metadatav1.VariableValue {
	return &metadatav1.VariableValue{Kind: &metadatav1.VariableValue_RedactedRef{RedactedRef: ref}}
}

// --- Merge: the namespace-only document write ---

// Merge integrates tmdb's metadata into the core document, writing ONLY the
// sources.<plugin_id> namespace (the plugin_id is the core-supplied namespace
// id, "tmdb"). The plugin never touches _provenance/_view/_stages — the core
// owns those and validates the namespace (arch §3.3). The reserved
// resolved_ids entry is stripped first: it is core-side identifier input
// (doc.identifiers), never a namespace field. The returned View bindings are
// a proposal (informational); the core recomputes _view authoritatively
// (arch §3.2 L2).
func (*sourceImpl) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	id := req.GetPluginId() // the namespace id the core directs this plugin to write
	if id == "" {
		id = pluginID
	}
	meta := map[string]any{}
	if in := req.GetIncoming(); in != nil {
		meta = in.AsMap()
	}
	delete(meta, resolvedIDsKey)
	data, _ := structpb.NewStruct(map[string]any{"sources": map[string]any{id: meta}})
	view := make([]*commonv1.ViewBinding, 0, len(meta))
	for field := range meta {
		view = append(view, &commonv1.ViewBinding{FieldPath: field, Source: id, Reason: "priority"})
	}
	return &metadatav1.MergeResult{
		Document: &commonv1.MediaDocument{Data: data},
		View:     view,
	}, nil
}
